import json
POLICIES = json.loads("""{
 "ci-deploy": {"Statement": [
   {"Effect": "Allow", "Action": "s3:*", "Resource": "arn:aws:s3:::artifacts/*"},
   {"Effect": "Allow", "Action": ["ecr:GetAuthorizationToken"], "Resource": "*"}]},
 "admin-ish": {"Statement": [
   {"Effect": "Allow", "Action": "*", "Resource": "*"}]},
 "public-bucket": {"Statement": [
   {"Effect": "Allow", "Principal": "*", "Action": "s3:GetObject", "Resource": "arn:aws:s3:::site/*"},
   {"Effect": "Deny", "Action": "*", "Resource": "*"}]}
}""")
def as_list(x):
    return x if isinstance(x, list) else [x]
for name in sorted(POLICIES):
    for st in as_list(POLICIES[name]["Statement"]):
        if st["Effect"] != "Allow":
            continue
        acts = as_list(st.get("Action", []))
        issues = []
        if "*" in acts:
            issues.append("all actions")
        issues += [f"wildcard {a}" for a in acts if a.endswith(":*")]
        if "*" in as_list(st.get("Resource", [])) and any(a == "*" or a.endswith(":*") for a in acts):
            issues.append("Resource *")
        if st.get("Principal") == "*":
            issues.append("public principal")
        if issues:
            print(f"{name}: {', '.join(issues)}")
